begin;
create table public.apostolic_battle_outcomes(id uuid primary key default gen_random_uuid(),attack_id uuid not null unique references public.apostolic_city_attacks(id)on delete cascade,attacker_id uuid not null references public.profiles(id)on delete cascade,defender_city_id uuid not null references public.apostolic_cities(id)on delete cascade,result text not null check(result in('victory','defeat','draw')),attacker_lost integer not null check(attacker_lost>=0),attacker_wounded integer not null check(attacker_wounded>=0),defender_lost integer not null check(defender_lost>=0),loot jsonb not null default'{}'::jsonb check(jsonb_typeof(loot)='object'and not(loot?'gems')),protection_until timestamptz not null,abuse_score smallint not null default 0 check(abuse_score between 0 and 100),resolved_at timestamptz not null default clock_timestamp());
create index apostolic_battle_outcomes_attacker_idx on public.apostolic_battle_outcomes(attacker_id,resolved_at desc);
create index apostolic_battle_outcomes_defender_idx on public.apostolic_battle_outcomes(defender_city_id,resolved_at desc);
alter table public.apostolic_battle_outcomes enable row level security;
create policy battle_outcomes_participants on public.apostolic_battle_outcomes for select to authenticated using(attacker_id=(select auth.uid())or exists(select 1 from public.apostolic_cities c where c.id=defender_city_id and c.owner_id=(select auth.uid())));
revoke all on public.apostolic_battle_outcomes from anon,authenticated;grant select on public.apostolic_battle_outcomes to authenticated;
create or replace function public.apostolic_get_battle_results()returns jsonb language sql stable security definer set search_path=''as $$with rows as(select o.id,o.result,c.name target_name,o.attacker_lost,o.attacker_wounded,o.defender_lost,o.loot,o.protection_until,o.resolved_at from public.apostolic_battle_outcomes o join public.apostolic_cities c on c.id=o.defender_city_id where o.attacker_id=(select auth.uid())order by o.resolved_at desc limit 30)select jsonb_build_object('outcomes',coalesce((select jsonb_agg(to_jsonb(r)order by resolved_at desc)from rows r),'[]'::jsonb),'summary',jsonb_build_object('victories',coalesce((select count(*)from public.apostolic_battle_outcomes where attacker_id=(select auth.uid())and result='victory'),0),'defeats',coalesce((select count(*)from public.apostolic_battle_outcomes where attacker_id=(select auth.uid())and result='defeat'),0),'lost',coalesce((select sum(attacker_lost)from public.apostolic_battle_outcomes where attacker_id=(select auth.uid())),0),'wounded',coalesce((select sum(attacker_wounded)from public.apostolic_battle_outcomes where attacker_id=(select auth.uid())),0)))$$;
create or replace function public.apostolic_prepare_city_attack(p_army_id uuid,p_defender_city_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());a public.apostolic_armies%rowtype;home public.apostolic_cities%rowtype;target public.apostolic_cities%rowtype;begin if uid is null or p_idempotency_key is null then raise exception'authentication required';end if;select*into a from public.apostolic_armies where id=p_army_id and owner_id=uid for update;if not found or a.status not in('ready','stationed')then raise exception'army unavailable';end if;select*into home from public.apostolic_cities where id=a.home_city_id;select*into target from public.apostolic_cities where id=p_defender_city_id;if not found or target.province_id<>home.province_id or target.owner_id=uid then raise exception'invalid target';end if;if exists(select 1 from public.apostolic_city_attack_protections where city_id=target.id and protected_until>clock_timestamp())then raise exception'target protected';end if;if exists(select 1 from public.apostolic_city_attacks where attacker_id=uid and idempotency_key=p_idempotency_key)then return public.apostolic_get_attack_center();end if;if exists(select 1 from public.apostolic_city_attacks where attacker_id=uid and status in('prepared','in_battle'))then raise exception'attack already active';end if;if exists(select 1 from public.apostolic_city_attacks where attacker_id=uid and prepared_at>clock_timestamp()-interval'5 minutes')then raise exception'attack cooldown';end if;if(select count(*)from public.apostolic_city_attacks where attacker_id=uid and defender_city_id=target.id and prepared_at>clock_timestamp()-interval'24 hours')>=3 then raise exception'daily target limit';end if;insert into public.apostolic_city_attacks(attacker_id,attacker_city_id,defender_city_id,army_id,expires_at,idempotency_key)values(uid,home.id,target.id,a.id,clock_timestamp()+interval'15 minutes',p_idempotency_key);update public.apostolic_armies set status='attacking'where id=a.id;return public.apostolic_get_attack_center();end;$$;
create or replace function public.apostolic_resolve_city_attack(p_attack_id uuid,p_battle_token uuid,p_result text)returns jsonb language plpgsql security definer set search_path=''as $$declare a public.apostolic_city_attacks%rowtype;army public.apostolic_armies%rowtype;loss integer;wounded integer;enemy_loss integer;loot jsonb:='{}'::jsonb;k text;available bigint;take bigint;protect_until timestamptz;recent_count integer;begin if p_result not in('victory','defeat','draw')then raise exception'invalid result';end if;select*into a from public.apostolic_city_attacks where id=p_attack_id and attacker_id=(select auth.uid())for update;if not found or a.battle_token<>p_battle_token then raise exception'attack unavailable';end if;if a.status='resolved'then return public.apostolic_get_attack_center();end if;if a.status<>'in_battle'or a.expires_at<=clock_timestamp()then raise exception'attack expired';end if;select*into army from public.apostolic_armies where id=a.army_id for update;loss:=least(greatest(army.total_units-1,0),case p_result when'victory'then greatest(1,army.total_units/20)when'draw'then greatest(1,army.total_units/12)else greatest(1,army.total_units/8)end);wounded:=least(greatest(army.total_units-loss-1,0),case p_result when'victory'then army.total_units/12 else army.total_units/8 end);enemy_loss:=case p_result when'victory'then greatest(1,army.total_units/10)when'draw'then greatest(1,army.total_units/18)else greatest(0,army.total_units/30)end;if p_result='victory'then for k in select unnest(array['wheat','cedar','stone','oil','gold'])loop select amount into available from public.apostolic_city_resources where city_id=a.defender_city_id and resource=k for update;take:=least(coalesce(available,0)/10,greatest(1,army.total_units/2));if take>0 then update public.apostolic_city_resources set amount=amount-take where city_id=a.defender_city_id and resource=k;insert into public.apostolic_city_resources(city_id,resource,amount)values(a.attacker_city_id,k,take)on conflict(city_id,resource)do update set amount=public.apostolic_city_resources.amount+excluded.amount;loot:=jsonb_set(loot,array[k],to_jsonb(take),true);end if;end loop;end if;select count(*)into recent_count from public.apostolic_city_attacks where attacker_id=a.attacker_id and defender_city_id=a.defender_city_id and prepared_at>clock_timestamp()-interval'24 hours';protect_until:=clock_timestamp()+case when p_result='victory'then interval'2 hours'when recent_count>=3 then interval'4 hours'else interval'30 minutes'end;update public.apostolic_city_attacks set status='resolved',result=p_result,resolved_at=clock_timestamp()where id=a.id;update public.apostolic_armies set status='ready',total_units=greatest(1,total_units-loss-wounded)where id=a.army_id;insert into public.apostolic_battle_outcomes(attack_id,attacker_id,defender_city_id,result,attacker_lost,attacker_wounded,defender_lost,loot,protection_until,abuse_score)values(a.id,a.attacker_id,a.defender_city_id,p_result,loss,wounded,enemy_loss,loot,protect_until,least(100,recent_count*25))on conflict(attack_id)do nothing;insert into public.apostolic_city_attack_protections(city_id,protected_until,reason)values(a.defender_city_id,protect_until,'post_battle_v150')on conflict(city_id)do update set protected_until=greatest(public.apostolic_city_attack_protections.protected_until,excluded.protected_until),reason=excluded.reason,updated_at=clock_timestamp();return public.apostolic_get_attack_center();end;$$;
revoke all on function public.apostolic_get_battle_results(),public.apostolic_prepare_city_attack(uuid,uuid,uuid),public.apostolic_resolve_city_attack(uuid,uuid,text)from public;
grant execute on function public.apostolic_get_battle_results(),public.apostolic_prepare_city_attack(uuid,uuid,uuid),public.apostolic_resolve_city_attack(uuid,uuid,text)to authenticated;
commit;
